<?php
namespace App\Models;
use App\Enums\UserRole; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Relations\{BelongsToMany,HasOne}; use Illuminate\Foundation\Auth\User as Authenticatable; use Illuminate\Notifications\Notifiable; use Laravel\Sanctum\HasApiTokens;
class User extends Authenticatable { use HasApiTokens,HasFactory,Notifiable; protected $fillable=['name','email','phone','password','role']; protected $hidden=['password','remember_token']; protected function casts():array{return ['password'=>'hashed','role'=>UserRole::class,'email_verified_at'=>'datetime'];} public function technicianProfile():HasOne{return $this->hasOne(TechnicianProfile::class);} public function categories():BelongsToMany{return $this->belongsToMany(ServiceCategory::class,'category_technician','technician_id','service_category_id');} }
